BEGIN;CREATE OR REPLACE FUNCTION public.office_institutions_read(p_workspace_id uuid,p_resource text,p_filter jsonb,p_limit integer,p_offset integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE f jsonb:=coalesce(p_filter,'{}');n bigint;rows jsonb;cap text;branch uuid;exact boolean:=false;purpose text;keykind text;s record;r text:=p_resource;BEGIN IF p_limit NOT BETWEEN 1 AND 50 OR p_offset<0 OR jsonb_typeof(f)<>'object' THEN RAISE EXCEPTION 'Invalid Institutions page request' USING ERRCODE='22023';END IF;IF EXISTS(SELECT 1 FROM jsonb_object_keys(f) k WHERE k NOT IN('id','q','status','branch_id','fund_id','event_id','purpose')) THEN RAISE EXCEPTION 'Unknown Institutions filter' USING ERRCODE='22023';END IF;IF r='bootstrap' THEN IF NOT EXISTS(SELECT 1 FROM public.office_memberships m JOIN public.office_industry_spaces i ON i.workspace_id=m.workspace_id AND i.industry_id='church' WHERE m.workspace_id=p_workspace_id AND m.user_id=auth.uid() AND m.status='active') THEN RAISE EXCEPTION 'Institutions membership required' USING ERRCODE='42501';END IF;SELECT*INTO s FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id;IF NOT FOUND OR NOT s.initialized THEN s.initialized:=false;s.version:=1;s.base_currency:='TZS';s.private_data_enabled:=false;s.storage_review_state:='unverified';s.storage_review_reference:=NULL;END IF;RETURN jsonb_build_object('workspace_id',p_workspace_id,'role',office_private.inst_role(p_workspace_id),'capabilities',jsonb_build_object('manage',office_private.inst_cap(p_workspace_id,'manage'),'people',office_private.inst_cap(p_workspace_id,'people'),'governance',office_private.inst_cap(p_workspace_id,'governance'),'finance',office_private.inst_cap(p_workspace_id,'finance'),'approve',office_private.inst_cap(p_workspace_id,'approve'),'facilities',office_private.inst_cap(p_workspace_id,'facilities'),'programmes',office_private.inst_cap(p_workspace_id,'programmes'),'staff',office_private.inst_cap(p_workspace_id,'staff'),'safeguarding',office_private.inst_cap(p_workspace_id,'safeguarding'),'privacy',office_private.inst_cap(p_workspace_id,'privacy'),'reports',office_private.inst_cap(p_workspace_id,'reports'),'audit',office_private.inst_cap(p_workspace_id,'audit')),'settings',jsonb_build_object('initialized',s.initialized,'version',s.version,'base_currency',s.base_currency,'private_data_enabled',s.private_data_enabled,'storage_review_state',s.storage_review_state,'storage_review_reference',s.storage_review_reference,'storage_review_recorded_by',s.storage_review_recorded_by,'storage_reviewed_by',s.storage_reviewed_by,'storage_review_decision_reference',s.storage_review_decision_reference),'scope_branch_id',office_private.inst_actor_branch(p_workspace_id),'summary',jsonb_build_object('organizations',(SELECT count(*) FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource='organizations' AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.data->>'branch_id'=office_private.inst_actor_branch(p_workspace_id)::text)),'people',(SELECT count(*) FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource='people' AND office_private.inst_cap(p_workspace_id,'people') AND s.private_data_enabled AND s.storage_review_state='approved' AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.data->>'branch_id'=office_private.inst_actor_branch(p_workspace_id)::text))));END IF;IF r='private_keys' THEN IF office_private.inst_role(p_workspace_id) IS NULL THEN RAISE EXCEPTION 'Institutions module role required' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('people',CASE WHEN office_private.inst_cap(p_workspace_id,'people') THEN coalesce((SELECT jsonb_build_object('configured',configured,'accessible',true,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',replace(encode(salt,'base64'),chr(10),''),'nonce',replace(encode(nonce,'base64'),chr(10),''),'ciphertext',replace(encode(ciphertext,'base64'),chr(10),'')) FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind='people'),jsonb_build_object('configured',false)) ELSE jsonb_build_object('configured',false) END,'safeguarding',CASE WHEN office_private.inst_role(p_workspace_id) IN('safeguarding_officer','privacy_officer') THEN coalesce((SELECT jsonb_build_object('configured',configured,'accessible',true,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',replace(encode(salt,'base64'),chr(10),''),'nonce',replace(encode(nonce,'base64'),chr(10),''),'ciphertext',replace(encode(ciphertext,'base64'),chr(10),'')) FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind='safeguarding'),jsonb_build_object('configured',false)) ELSE CASE WHEN office_private.inst_cap(p_workspace_id,'manage') THEN jsonb_build_object('configured',EXISTS(SELECT 1 FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind='safeguarding' AND configured),'accessible',false) ELSE jsonb_build_object('configured',false) END END);END IF;IF office_private.inst_role(p_workspace_id) IS NULL THEN RAISE EXCEPTION 'Institutions module role required' USING ERRCODE='42501';END IF;IF r NOT IN('organizations','branches','bodies','people','appointments','meetings','resolutions','funds','budgets','contributions','payment_requests','bank_lines','reconciliations','facilities','assets','asset_moves','programmes','events','attendance','staff_assignments','credentials','filings','evidence','safeguarding','privacy_requests','reports','ledger','audit','team_members','roles','people_index','attendance_index','safeguarding_index') THEN RAISE EXCEPTION 'Unknown Institutions resource' USING ERRCODE='22023';END IF;IF r IN('people_index','attendance_index','safeguarding_index') THEN keykind:=CASE WHEN r='safeguarding_index' THEN 'safeguarding' ELSE 'people' END;cap:=CASE WHEN r='safeguarding_index' THEN 'safeguarding' ELSE 'people' END;IF NOT office_private.inst_cap(p_workspace_id,cap) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_keys k WHERE k.workspace_id=p_workspace_id AND k.kind=keykind AND k.configured) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_settings z WHERE z.workspace_id=p_workspace_id AND z.private_data_enabled AND z.storage_review_state='approved') THEN RAISE EXCEPTION 'Private index gate closed' USING ERRCODE='55000';END IF;END IF;cap:=office_private.inst_resource_cap(CASE WHEN r IN('people_index','attendance_index','safeguarding_index') THEN CASE WHEN r='safeguarding_index' THEN 'safeguarding' ELSE 'people' END ELSE r END);IF r NOT IN('organizations','branches','bodies','roles') AND cap IS NOT NULL AND NOT office_private.inst_cap(p_workspace_id,cap) THEN RAISE EXCEPTION 'Resource capability denied' USING ERRCODE='42501';END IF;IF r IN('organizations','branches','bodies') AND NOT office_private.inst_member(p_workspace_id) THEN RAISE EXCEPTION 'Institutions membership required' USING ERRCODE='42501';END IF;IF r IN('people','attendance','safeguarding') THEN purpose:=f->>'purpose';IF NOT(f ? 'id') OR f->>'id' IS NULL OR purpose IS NULL OR purpose NOT IN('administration','direct_service','record_correction','safeguarding_response','compliance_review','audit') THEN RAISE EXCEPTION 'Sensitive reads require exact id and validated purpose' USING ERRCODE='55000';END IF;keykind:=CASE WHEN r='safeguarding' THEN 'safeguarding' ELSE 'people' END;IF NOT office_private.inst_cap(p_workspace_id,CASE WHEN r='safeguarding' THEN 'safeguarding' ELSE 'people' END) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_keys k WHERE k.workspace_id=p_workspace_id AND k.kind=keykind AND k.configured) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_settings z WHERE z.workspace_id=p_workspace_id AND z.private_data_enabled AND z.storage_review_state='approved') THEN RAISE EXCEPTION 'Private gate closed' USING ERRCODE='55000';END IF;exact:=true;END IF;IF r IN('people','attendance','safeguarding') AND f ? 'q' THEN RAISE EXCEPTION 'Private search is not permitted' USING ERRCODE='22023';END IF;IF f ? 'id' AND(f->>'id'!~ '^[0-9a-fA-F-]{36}$') THEN RAISE EXCEPTION 'Invalid id filter' USING ERRCODE='22023';END IF;IF f ? 'branch_id' AND(f->>'branch_id'!~ '^[0-9a-fA-F-]{36}$') THEN RAISE EXCEPTION 'Invalid branch filter' USING ERRCODE='22023';END IF;branch:=NULLIF(f->>'branch_id','')::uuid;IF branch IS NOT NULL AND NOT office_private.inst_scope(p_workspace_id,branch) THEN RAISE EXCEPTION 'Institutions branch scope denied' USING ERRCODE='42501';END IF;IF r IN('reports','ledger','audit','roles','team_members') THEN IF r='reports' THEN SELECT count(*) INTO n FROM public.office_institutions_reports x WHERE x.workspace_id=p_workspace_id AND office_private.inst_cap(p_workspace_id,office_private.inst_report_cap(x.report_type)) AND(f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND(f->>'branch_id' IS NULL OR x.branch_id=(f->>'branch_id')::uuid) AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.branch_id=office_private.inst_actor_branch(p_workspace_id));SELECT coalesce(jsonb_agg(v ORDER BY period_end DESC,id),'[]') INTO rows FROM(SELECT x.period_end,x.id,jsonb_build_object('id',x.id,'workspace_id',x.workspace_id,'version',x.version,'report_type',x.report_type,'period_start',x.period_start,'period_end',x.period_end,'title',x.title,'branch_id',x.branch_id,'snapshot',x.snapshot,'created_by',x.created_by,'created_at',x.created_at) v FROM public.office_institutions_reports x WHERE x.workspace_id=p_workspace_id AND office_private.inst_cap(p_workspace_id,office_private.inst_report_cap(x.report_type)) AND(f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND(f->>'branch_id' IS NULL OR x.branch_id=(f->>'branch_id')::uuid) AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.branch_id=office_private.inst_actor_branch(p_workspace_id)) ORDER BY x.period_end DESC,x.id OFFSET p_offset LIMIT p_limit) q;ELSIF r='ledger' THEN IF NOT office_private.inst_cap(p_workspace_id,'finance') THEN RAISE EXCEPTION 'Finance capability required' USING ERRCODE='42501';END IF;SELECT count(*) INTO n FROM public.office_institutions_ledger x WHERE x.workspace_id=p_workspace_id AND(f->>'branch_id' IS NULL OR x.branch_id=(f->>'branch_id')::uuid) AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.branch_id=office_private.inst_actor_branch(p_workspace_id));SELECT coalesce(jsonb_agg(v ORDER BY posted_on DESC,id),'[]') INTO rows FROM(SELECT x.posted_on,x.id,jsonb_build_object('id',x.id,'fund_id',x.fund_id,'kind',x.kind,'amount',x.amount,'reference',x.reference,'source_id',x.source_id,'posted_on',x.posted_on,'method',x.method,'budget_id',x.budget_id,'branch_id',x.branch_id) v FROM public.office_institutions_ledger x WHERE x.workspace_id=p_workspace_id AND(f->>'branch_id' IS NULL OR x.branch_id=(f->>'branch_id')::uuid) AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.branch_id=office_private.inst_actor_branch(p_workspace_id)) ORDER BY x.posted_on DESC,x.id OFFSET p_offset LIMIT p_limit) q;ELSE IF r='audit' AND NOT office_private.inst_cap(p_workspace_id,'audit') THEN RAISE EXCEPTION 'Audit capability required' USING ERRCODE='42501';END IF;IF r IN('roles','team_members') AND NOT office_private.inst_cap(p_workspace_id,'manage') THEN RAISE EXCEPTION 'Manage capability required' USING ERRCODE='42501';END IF;SELECT count(*) INTO n FROM public.office_institutions_roles x WHERE x.workspace_id=p_workspace_id AND x.active;SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',x.user_id,'role',x.role,'branch_id',x.branch_id,'active',x.active,'version',x.version) ORDER BY x.user_id),'[]') INTO rows FROM public.office_institutions_roles x WHERE x.workspace_id=p_workspace_id AND x.active OFFSET p_offset LIMIT p_limit;END IF;RETURN jsonb_build_object('rows',rows,'total_count',n,'limit',p_limit,'offset',p_offset,'has_more',p_offset+jsonb_array_length(rows)<n);END IF;IF r IN('people_index','attendance_index','safeguarding_index') THEN r:=CASE WHEN r='people_index' THEN 'people' WHEN r='attendance_index' THEN 'attendance' ELSE 'safeguarding' END;END IF;SELECT count(*) INTO n FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource=r AND(f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND(f->>'status' IS NULL OR x.status=f->>'status') AND(f->>'branch_id' IS NULL OR x.data->>'branch_id'=f->>'branch_id') AND(f->>'fund_id' IS NULL OR x.data->>'fund_id'=f->>'fund_id') AND(f->>'event_id' IS NULL OR x.data->>'event_id'=f->>'event_id') AND(r IN('people','attendance','safeguarding') OR f->>'q' IS NULL OR(x.data->>'code' ILIKE('%'||coalesce(f->>'q','')||'%') OR x.data->>'name' ILIKE('%'||coalesce(f->>'q','')||'%') OR x.data->>'title_public' ILIKE('%'||coalesce(f->>'q','')||'%'))) AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.data->>'branch_id'=office_private.inst_actor_branch(p_workspace_id)::text);SELECT coalesce(jsonb_agg(v ORDER BY updated_at DESC,id),'[]') INTO rows FROM(SELECT x.updated_at,x.id,CASE WHEN r IN('people','attendance','safeguarding') AND exact THEN office_private.inst_safe_row(x)||jsonb_build_object('nonce',x.data->'nonce','ciphertext',x.data->'ciphertext','lawful_basis',x.data->'lawful_basis','notice_reference',x.data->'notice_reference','retention_until',x.data->'retention_until') ELSE office_private.inst_safe_row(x) END v FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource=r AND(f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND(f->>'status' IS NULL OR x.status=f->>'status') AND(f->>'branch_id' IS NULL OR x.data->>'branch_id'=f->>'branch_id') AND(office_private.inst_actor_branch(p_workspace_id) IS NULL OR x.data->>'branch_id'=office_private.inst_actor_branch(p_workspace_id)::text) ORDER BY x.updated_at DESC,x.id OFFSET p_offset LIMIT p_limit) q;INSERT INTO public.office_institutions_audit(workspace_id,actor_id,resource,action,purpose,metadata) VALUES(p_workspace_id,auth.uid(),p_resource,'read',f->>'purpose',jsonb_build_object('id',f->>'id','count',jsonb_array_length(rows),'offset',p_offset,'limit',p_limit));RETURN jsonb_build_object('rows',rows,'total_count',n,'limit',p_limit,'offset',p_offset,'has_more',p_offset+jsonb_array_length(rows)<n);END $$;REVOKE ALL ON FUNCTION public.office_institutions_read(uuid,text,jsonb,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.office_institutions_read(uuid,text,jsonb,integer,integer) TO authenticated;COMMIT;
